  function getCustomCache() {
    try {
      const stored = localStorage.getItem('ss_brandfetch_logo_cache');
      return stored ? JSON.parse(stored) : {};
    } catch (e) {
      return {};
    }
  }

  function setCustomCache(cache) {
    try {
      localStorage.setItem('ss_brandfetch_logo_cache', JSON.stringify(cache));
    } catch (e) {}
  }


  function _svgToDataUrl(svgStr) {
    if (!svgStr) return '';
    if (typeof btoa !== 'undefined') {
      try {
        return 'data:image/svg+xml;base64,' + btoa(unescape(encodeURIComponent(svgStr)));
      } catch (e) {}
    }
    if (typeof Buffer !== 'undefined') {
      return 'data:image/svg+xml;base64,' + Buffer.from(svgStr).toString('base64');
    }
    return 'data:image/svg+xml;utf8,' + encodeURIComponent(svgStr);
  }

  function getLogo(bankName) {
    if (!bankName) return null;
    const key = normalizeKey(bankName);

    if (FULL_LOGOS[key]) {
      if (!FULL_LOGOS[key].dataUrl && FULL_LOGOS[key].svg) {
        FULL_LOGOS[key].dataUrl = _svgToDataUrl(FULL_LOGOS[key].svg);
      }
      return FULL_LOGOS[key].dataUrl;
    }

    const cache = getCustomCache();
    if (cache[key]) return cache[key];

    const upper = bankName.trim().toUpperCase();
    if (FULL_LOGOS[upper]) {
      if (!FULL_LOGOS[upper].dataUrl && FULL_LOGOS[upper].svg) {
        FULL_LOGOS[upper].dataUrl = _svgToDataUrl(FULL_LOGOS[upper].svg);
      }
      return FULL_LOGOS[upper].dataUrl;
    }
    if (cache[upper]) return cache[upper];

    return null;
  }

  function getSvg(bankName) {
    const key = normalizeKey(bankName);
    if (FULL_LOGOS[key]) return FULL_LOGOS[key].svg;
    return null;
  }

  function hasLogo(bankName) {
    return !!getLogo(bankName);
  }

  async function fetchFromBrandfetch(bankNameOrDomain) {
    if (!bankNameOrDomain) return null;
    const key = normalizeKey(bankNameOrDomain);
    const existing = getLogo(bankNameOrDomain);
    if (existing) {
      return { success: true, isLocal: true, dataUrl: existing };
    }
    return { success: true, dataUrl: existing };
  }

  return {
    getLogo,
    getSvg,
    hasLogo,
    fetchFromBrandfetch,
    normalizeKey,
    BANK_DOMAINS,
    FULL_LOGOS
  };
